import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }


    public static void main(String[] args) throws IOException {
        String s = next();
        int m = nextInt();
        String kit = "";
        long[] rating = new long[m];
        if (m > 0) {
            kit = next();
            for (int i = 0; i < m; i++) rating[i] = nextLong();
        }
        long balance = 0, low = 0;
        for (int i = 0; i < s.length(); i++) {
            balance += s.charAt(i) == '(' ? 1 : -1;
            low = Math.min(low, balance);
        }
        // Forced: enough '(' to cover the lowest prefix, enough ')' to close the final balance.
        long left = -low, right = left + balance;
        long[] a = new long[m], b = new long[m];
        int na = 0, nb = 0;
        for (int i = 0; i < m; i++) {
            if (kit.charAt(i) == '(') a[na++] = rating[i];
            else b[nb++] = rating[i];
        }
        // Sort ascending and read from the end for descending order.
        Arrays.sort(a, 0, na);
        Arrays.sort(b, 0, nb);
        long answer = 0;
        for (int i = 0; i < Math.min(left, na); i++) answer += a[na - 1 - i];
        for (int i = 0; i < Math.min(right, nb); i++) answer += b[nb - 1 - i];
        // Extra brackets come in matched pairs; take the best remaining pair while it helps.
        while (left < na && right < nb && a[na - 1 - (int) left] + b[nb - 1 - (int) right] > 0) {
            answer += a[na - 1 - (int) left] + b[nb - 1 - (int) right];
            left++;
            right++;
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"slices"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func next() string {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[start:pos])
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	s := next()
	m := int(nextInt())
	kit := ""
	rating := make([]int64, m)
	if m > 0 {
		kit = next()
		for i := range rating {
			rating[i] = nextInt()
		}
	}
	balance, low := 0, 0
	for i := 0; i < len(s); i++ {
		if s[i] == '(' {
			balance++
		} else {
			balance--
		}
		low = min(low, balance)
	}
	// Forced: enough '(' to cover the lowest prefix, enough ')' to close the final balance.
	left := -low
	right := left + balance
	var a, b []int64
	for i := 0; i < m; i++ {
		if kit[i] == '(' {
			a = append(a, rating[i])
		} else {
			b = append(b, rating[i])
		}
	}
	desc := func(x, y int64) int {
		if x > y {
			return -1
		}
		if x < y {
			return 1
		}
		return 0
	}
	slices.SortFunc(a, desc)
	slices.SortFunc(b, desc)
	answer := int64(0)
	for i := 0; i < min(left, len(a)); i++ {
		answer += a[i]
	}
	for i := 0; i < min(right, len(b)); i++ {
		answer += b[i]
	}
	// Extra brackets come in matched pairs; take the best remaining pair while it helps.
	for left < len(a) && right < len(b) && a[left]+b[right] > 0 {
		answer += a[left] + b[right]
		left++
		right++
	}
	fmt.Println(answer)
}
